import React, { useState } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  Button,
  InputAdornment,
  IconButton,
  Alert,
  CircularProgress,
  Divider
} from '@mui/material';
import {
  Visibility,
  VisibilityOff,
  Email,
  Lock
} from '@mui/icons-material';
import { useTheme } from '@mui/material/styles';

// Custom TextField Component
const CustomTextField = ({ icon, ...props }) => {
  const theme = useTheme();

  return (
    <TextField
      {...props}
      variant="outlined"
      fullWidth
      placeholder={props.placeholder}
      InputProps={{
        startAdornment: icon && (
          <InputAdornment position="start">
            <Box sx={{ color: '#6b7280', fontSize: 20 }}>
              {icon}
            </Box>
          </InputAdornment>
        ),
        sx: {
          backgroundColor: '#ffffff',
          height: '56px',
          '& .MuiOutlinedInput-root': {
            borderRadius: '8px',
            '& fieldset': {
              borderColor: '#d1d5db',
              borderWidth: '1px',
            },
            '&:hover fieldset': {
              borderColor: '#9ca3af',
            },
            '&.Mui-focused fieldset': {
              borderColor: '#3b82f6',
              borderWidth: '2px',
            },
          },
        },
      }}
    />
  );
};

// Primary Button Component
const PrimaryButton = ({ children, loading, ...props }) => {
  return (
    <Button
      {...props}
      variant="contained"
      fullWidth
      disabled={loading}
      sx={{
        backgroundColor: '#3b82f6',
        color: '#ffffff',
        py: 2,
        borderRadius: '8px',
        fontSize: '16px',
        fontWeight: 500,
        textTransform: 'none',
        boxShadow: '0 1px 2px rgba(0, 0, 0, 0.05)',
        '&:hover': {
          backgroundColor: '#2563eb',
          boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
        },
        '&:active': {
          backgroundColor: '#1d4ed8',
        },
        '&.Mui-disabled': {
          backgroundColor: '#e5e7eb',
        },
      }}
    >
      {loading ? (
        <CircularProgress size={20} color="inherit" />
      ) : (
        children
      )}
    </Button>
  );
};

// Auth Card Component
const AuthCard = ({ children }) => {
  return (
    <Card
      sx={{
        maxWidth: 432,
        width: '100%',
        backgroundColor: '#ffffff',
        borderRadius: '16px',
        boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)',
        border: '1px solid #f3f4f6',
      }}
    >
      <CardContent sx={{ p: 4 }}>
        {children}
      </CardContent>
    </Card>
  );
};

// App Header Component
const AppHeader = () => {
  return (
    <Box sx={{ textAlign: 'center', mb: 6 }}>
      <Box
        component="img"
        sx={{
          height: 40,
          mb: 4,
        }}
        alt="Site Survey Tool"
        src="/logo.svg" // You can replace this with actual logo
      />
      <Typography
        variant="h4"
        sx={{
          fontWeight: 600,
          color: '#111827',
          mb: 1,
          fontSize: '1.875rem',
          lineHeight: '2.25rem',
        }}
      >
        Sign in to your account
      </Typography>
    </Box>
  );
};

// Main Login Form Component
const LoginForm = ({ 
  formData, 
  errors, 
  loading, 
  error, 
  onChange, 
  onSubmit, 
  onAutoFill, 
  onTogglePassword 
}) => {
  const [showPassword, setShowPassword] = useState(false);

  const handleChange = (e) => {
    onChange(e);
  };

  const handleSubmit = (e) => {
    onSubmit(e);
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
    onTogglePassword();
  };

  return (
    <Box
      sx={{
        minHeight: '100vh',
        backgroundColor: '#ffffff',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        p: 2,
        fontFamily: '"Inter", "Roboto", "Helvetica", "Arial", sans-serif',
      }}
    >
      <AuthCard>
        <AppHeader />

        {error && (
          <Alert 
            severity="error" 
            sx={{ 
              mb: 3,
              borderRadius: '8px',
              '& .MuiAlert-message': {
                fontSize: '0.875rem',
              }
            }}
          >
            {error}
          </Alert>
        )}

        <Box component="form" onSubmit={handleSubmit} sx={{ width: '100%' }}>
          <CustomTextField
            name="email"
            type="email"
            placeholder="Enter your email"
            value={formData.email}
            onChange={handleChange}
            error={!!errors.email}
            helperText={errors.email}
            icon={<Email />}
            disabled={loading}
            sx={{ mb: 3 }}
          />

          <CustomTextField
            name="password"
            type={showPassword ? 'text' : 'password'}
            placeholder="Enter your password"
            value={formData.password}
            onChange={handleChange}
            error={!!errors.password}
            helperText={errors.password}
            icon={<Lock />}
            disabled={loading}
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <IconButton
                    onClick={togglePasswordVisibility}
                    edge="end"
                    disabled={loading}
                    sx={{ color: '#6b7280' }}
                  >
                    {showPassword ? <VisibilityOff /> : <Visibility />}
                  </IconButton>
                </InputAdornment>
              ),
            }}
            sx={{ mb: 4 }}
          />

          <PrimaryButton
            type="submit"
            loading={loading}
          >
            Sign in
          </PrimaryButton>
        </Box>

        <Box sx={{ textAlign: 'center', mt: 3 }}>
          <Typography
            variant="body2"
            sx={{
              color: '#6b7280',
              fontSize: '0.875rem',
            }}
          >
            Forgot your password?{' '}
            <Box
              component="a"
              href="#"
              sx={{
                color: '#3b82f6',
                textDecoration: 'none',
                fontWeight: 500,
                '&:hover': {
                  textDecoration: 'underline',
                },
              }}
            >
              Click here
            </Box>
          </Typography>
        </Box>
      </AuthCard>
    </Box>
  );
};

export default LoginForm;
